<?php declare(strict_types=1);namespace App\Controllers\Api;use App\Core\I18n;use App\Core\Request;use App\Core\Response;final class StatusController{public function index(Request $G):Response{return Response::json(['ok'=>true,'service'=>'toutpvr-portal','version'=>TP_VERSION,'time'=>gmdate('c')]);}public function i18n(Request $k,string $i):Response{if(!in_array($i,I18n::LANGUAGES,true)){return Response::error('not_found',404);}return Response::json(I18n::load($i))->withHeader('Cache-Control','public, max-age=3600');}}